import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { gzipSync, gunzipSync } from 'node:zlib'
import { createHash } from 'node:crypto'
import assert from 'node:assert/strict'
const root = 'benchmark-results/heavy-scenes/', base = 'c5dbb0c96a7853111f4d3760efedfb6b5b9a597a'
const output = 'docs/benchmarks/depth-volume-batching-2026-10-27.json'
const rawPath = root + 'volume-batch-v2-2026-10-27.json', reviewPath = root + 'volume-batch-review-2026-10-27.json'
const sha = bytes => createHash('sha256').update(bytes).digest('hex')
const read = file => { const bytes = readFileSync(file); return bytes[0] === 255 && bytes[1] === 254 ? bytes.subarray(2).toString('utf16le') : bytes.toString('utf8').replace(/^\uFEFF/, '') }
const json = file => JSON.parse(read(file))
const stats = values => {
  const a = values.slice().sort((x, y) => x - y)
  assert.ok(a.length)
  const q = p => a[Math.ceil(a.length * p) - 1]
  return { count: a.length, p50: q(.5), p95: q(.95), p99: q(.99), max: a.at(-1), mean: values.reduce((a, b) => a + b, 0) / a.length }
}
const packed = file => { const bytes = readFileSync(file); return { path: file, bytes: bytes.length, sha256: sha(bytes), encoding: 'gzip+base64', gzipBase64: gzipSync(bytes, { level: 9 }).toString('base64') } }
const unpack = value => { const bytes = gunzipSync(Buffer.from(value.gzipBase64, 'base64')); assert.equal(bytes.length, value.bytes); assert.equal(sha(bytes), value.sha256); return JSON.parse(bytes.toString('utf8')) }
function verifyProfile(report, smoke = false) {
  assert.equal(report.outcome, 'completed'); assert.equal(report.base, base); assert.equal(report.smoke, smoke)
  assert.equal(report.rows.length, smoke ? 2 : 24); assert.equal(report.scenes.length, smoke ? 1 : 2)
  assert.equal(report.images.length, smoke ? 1 : 6); assert.ok(report.cloudResponses > 0)
  for (const key of ['errors', 'warnings', 'assetFailures', 'sourceModuleRequests']) assert.deepEqual(report[key], [])
  for (const [file, hash] of Object.entries(report.sourceHashes)) assert.equal(sha(readFileSync(file)), hash, file)
  for (const file of report.buildFiles) assert.equal(sha(readFileSync(report.frozenBundle + '/' + file.path)), file.sha256)
  for (const request of report.requests.filter(row => row.type === 'script')) {
    assert.equal(request.origin, 'http://127.0.0.1:8096')
    assert.ok(report.buildFiles.some(file => request.path === '/titan-engine-dev/' + file.path), request.path)
  }
  for (const scene of report.scenes) {
    assert.doesNotMatch(scene.renderer, /SwiftShader|software|llvmpipe/i)
    assert.equal(scene.afterMenu.scenario, null); assert.deepEqual(scene.afterMenu.memory, { geometries: 1, textures: 0 })
    assert.equal(scene.afterMenu.programs, 0); assert.equal(scene.afterMenu.pendingBakes, 0); assert.equal(scene.afterMenu.bakeBytes, 0)
    assert.deepEqual(scene.afterMenu.volumes, []); assert.deepEqual(scene.afterMenu.streamers, [])
  }
  for (const row of report.rows) {
    const n = smoke ? 8 : 120
    assert.equal(row.frames, n); assert.equal(row.starts.length, n); assert.equal(row.wholeCpu.length, n)
    assert.deepEqual(row.intervals, row.starts.slice(1).map((value, i) => value - row.starts[i]))
    assert.deepEqual(row.summary.intervals, stats(row.intervals)); assert.deepEqual(row.summary.wholeCpu, stats(row.wholeCpu))
    assert.equal(row.initial.pendingBakes, 0); assert.equal(row.final.pendingBakes, 0); assert.equal(row.restoration.complete, true)
    assert.deepEqual(row.initial.camera, row.view.camera); assert.deepEqual(row.positions[0].position, row.view.camera)
    assert.ok(Math.abs(Math.hypot(...row.positions[1].position.map((value, i) => value - row.positions[0].position[i])) - (row.motion ? 2 : 0)) < 1e-8)
    assert.equal(row.resolves.length, n)
    assert.ok(row.resolves.every(value => value === (row.id === 13 && !row.batch ? 4 : 2)))
    const values = {}, calls = {}
    for (const sample of row.gpu) {
      assert.ok(Number.isInteger(sample.frame) && sample.frame >= 0 && sample.frame < n && Number.isFinite(sample.ms) && sample.ms > 0)
      ;(values[sample.key] ??= Array(n).fill(0))[sample.frame] += sample.ms
      ;(calls[sample.key] ??= Array(n).fill(0))[sample.frame]++
    }
    assert.deepEqual(values, row.gpuPerFrame); assert.deepEqual(calls, row.gpuCalls)
    assert.deepEqual(row.summary.gpu, Object.fromEntries(Object.entries(values).map(([key, samples]) => [key, stats(samples)])))
    assert.equal(Object.keys(values).length, row.mode === 'passes' ? 10 : 1)
    assert.ok(Object.values(calls).every(values => values.every(count => count === 1)))
    for (const target of row.hardware) {
      assert.deepEqual([target.width, target.height, target.requestedSamples], [1280, 720, 8])
      assert.equal(target.colorRenderbuffers.length, 1)
      assert.deepEqual(target.colorRenderbuffers[0], { samples: 8, format: 34842 })
    }
  }
  for (const image of report.images) {
    assert.equal(image.records.length, 3)
    const reference = readFileSync(image.records[0].rgbaPath)
    for (const record of image.records) {
      const rgba = readFileSync(record.rgbaPath)
      assert.equal(rgba.length, 1280 * 720 * 4); assert.ok(rgba.equals(reference))
      assert.equal(sha(rgba), record.rgbaSha256); assert.equal(sha(readFileSync(record.pngPath)), record.pngSha256)
      assert.equal(record.hdrSha256, image.records[0].hdrSha256); assert.equal(record.hdrBytes, 1280 * 720 * 8)
    }
    for (const check of [image.control, image.candidate]) for (const data of [check.rgba, check.hdr]) {
      assert.equal(data.differences, 0); assert.equal(data.max, 0); assert.equal(data.elements, 1280 * 720 * 4)
    }
  }
}
function analyze(report) {
  return [13, 12].flatMap(id => [false, true].map(motion => {
    const stages = {}
    for (const mode of ['passes', 'gpu-frame']) {
      const key = mode === 'passes' ? '2:DepthVolumePass' : 'whole-frame'
      const selected = report.rows.filter(row => row.id === id && row.motion === motion && row.mode === mode)
      const baseline = stats(selected.filter(row => !row.batch).flatMap(row => row.gpuPerFrame[key]))
      const candidate = stats(selected.filter(row => row.batch).flatMap(row => row.gpuPerFrame[key]))
      stages[mode] = { baseline, candidate, p50ReductionMs: baseline.p50 - candidate.p50, p50ReductionPercent: (baseline.p50 - candidate.p50) / baseline.p50 * 100,
        windows: selected.map(row => ({ repetition: row.repetition, batch: row.batch, gpu: row.summary.gpu[key], resolves: [...new Set(row.resolves)] })) }
    }
    return { id, motion, stages }
  }))
}
const fixedSources = [root + 'archive-volume-batch-2026-10-27.mjs', root + 'write-volume-batch-audit-2026-10-27.mjs', root + 'prepare-volume-batch-v2-2026-10-27.mjs',
  root + 'run-volume-batch-2026-10-27.mjs', root + 'volume-batch-2026-10-27.browser.js',
  'docs/superpowers/plans/2026-10-27-depth-volume-batching.md']
const logs = ['volume-batch-unit-red-2026-10-27.log', 'volume-batch-unit-red-native-2026-10-27.log', 'volume-batch-gpu-red-2026-10-27.log',
  'volume-batch-types-2026-10-27.log', 'volume-batch-unit-green-2026-10-27.log', 'volume-batch-gpu-green-2026-10-27.log', 'volume-batch-build-2026-10-27.log',
  'volume-batch-smoke-2026-10-27.log', 'volume-batch-v2-smoke-2026-10-27.log', 'volume-batch-v2-full-2026-10-27.log',
  'volume-batch-full-unit-2026-10-27.log', 'volume-batch-lint-2026-10-27.log', 'volume-batch-full-browser-2026-10-27.log', 'volume-batch-swiftshader-2026-10-27.log'].map(file => root + file)
const reports = ['volume-batch-gpu-red-results-2026-10-27.json', 'volume-batch-gpu-green-results-2026-10-27.json',
  'volume-batch-full-browser-results-2026-10-27.json', 'volume-batch-swiftshader-results-2026-10-27.json', 'volume-batch-2026-10-27-smoke.json'].map(file => root + file)
function verify(archive) {
  assert.equal(archive.base, base)
  const report = unpack(archive.rawProfile), smoke = unpack(archive.smoke)
  verifyProfile(report); verifyProfile(smoke, true)
  assert.deepEqual(archive.analysis, analyze(report)); assert.deepEqual(archive.buildFiles, report.buildFiles)
  for (const file of archive.provenance) { const bytes = readFileSync(file.path); assert.equal(bytes.length, file.bytes); assert.equal(sha(bytes), file.sha256, file.path) }
  for (const [file, content] of Object.entries(archive.sources)) assert.equal(content, read(file))
  for (const [file, content] of Object.entries(archive.logs)) assert.equal(content, read(file))
  for (const packedReport of archive.reports) unpack(packedReport)
  const native = json(root + 'volume-batch-full-browser-results-2026-10-27.json')
  const software = json(root + 'volume-batch-swiftshader-results-2026-10-27.json')
  assert.deepEqual([native.stats.expected, native.stats.unexpected, native.stats.skipped, native.stats.flaky], [50, 0, 0, 0])
  assert.deepEqual([software.stats.expected, software.stats.unexpected, software.stats.skipped, software.stats.flaky], [2, 0, 0, 0])
  assert.match(read(root + 'volume-batch-full-unit-2026-10-27.log'), /5642 passed/)
  assert.match(read(root + 'volume-batch-full-unit-2026-10-27.log'), /7 skipped/)
  assert.match(read(root + 'volume-batch-build-2026-10-27.log'), /built in 10\.26s/)
  assert.doesNotMatch(read(root + 'volume-batch-lint-2026-10-27.log'), /[1-9]\d* problems|\berror\b/i)
  if (archive.review) assert.deepEqual(archive.review, json(reviewPath))
  console.log(JSON.stringify({ verified: true, hashes: archive.provenance.length, buildFiles: report.buildFiles.length, windows: report.rows.length,
    frames: report.rows.reduce((sum, row) => sum + row.frames, 0), queries: report.rows.reduce((sum, row) => sum + row.gpu.length, 0), images: report.images.length, cloud: report.cloudResponses }))
}
if (process.argv.includes('--verify')) verify(json(output))
else {
  const report = json(rawPath)
  const sources = [...new Set([...fixedSources, ...Object.keys(report.sourceHashes)])]
  const imageFiles = [...report.images, ...json(root + 'volume-batch-v2-2026-10-27-smoke.json').images, ...json(root + 'volume-batch-2026-10-27-smoke.json').images]
    .flatMap(image => image.records.flatMap(record => [record.rgbaPath, record.pngPath]))
  const paths = [...new Set([...sources, ...logs, ...reports, ...imageFiles, rawPath, root + 'volume-batch-v2-2026-10-27-smoke.json', ...(existsSync(reviewPath) ? [reviewPath] : [])])]
  const archive = {
    base, createdAt: new Date().toISOString(), title: 'Batch consecutive direct depth volumes without changing MSAA composition',
    rawProfile: packed(rawPath), smoke: packed(root + 'volume-batch-v2-2026-10-27-smoke.json'), analysis: analyze(report), buildFiles: report.buildFiles,
    sources: Object.fromEntries(sources.map(file => [file, read(file)])), logs: Object.fromEntries(logs.map(file => [file, read(file)])), reports: reports.map(packed),
    validation: { unitPassed: 5642, unitSkipped: 7, nativeBrowserPassed: 50, swiftShaderPassed: 2, newUnitCases: 23, newGpuProbes: 2,
      typecheckBuild: true, lint: true, exactSyntheticHdrAndPostDrawDepth: true, exactRealSceneHdrAndRgba: true, realScenePosesPerScene: 3,
      baselineBeforeAfterControls: true, qualitySettingsChanged: false, pngViewed: [13, 12] },
    scope: [
      'Single AMD/ANGLE D3D11 native Chrome,1280x720,DPR1, actual RGBA16F8xMSAA. Same production build, baseline capability disabled vs enabled; original individual render path is retained. Build bytes and input source hashes are frozen.',
      '24 windows x120frames=2880 measured frames. Pass windows have2repetitions, forward and reversed candidate/baseline order; separate whole-frame windows have1pair each. Camera moves2TU/360degrees by frame index, not fixed real-time speed. Simulation continues; cache, scheduling and thermal effects are not fully controlled.',
      'GPU query polling and hardware readbacks occur after each window. Timings are elapsed GPU scopes and can include CPU submission gaps; they are not pure shader-busy time or presentation FPS. Pool per-frame values before quantiles; do not add or subtract medians from separate scopes to infer a decomposition.',
      'Three frozen poses per real scene: baseline-before/candidate/baseline-after,16render(0)frames each with reset temporal-history phases. Final RGBA bytes/PNG are saved locally with hashes; HDR after DepthVolumePass is compared exactly in-browser and hashed, not saved as raw bytes. Synthetic fixtures compare exact HDR and pre/post draw depth at requested0/4/8samples and2poses in both depth-volume and front-volume passes.',
      'Front-volume fixture supplies the front-volume list to LensFrontPass; full active gravitational-lens transitions and unrelated scene contents are not newly benchmarked. Existing full native and unit suites remain green. Pulsar opts into the same leaf/uniform callback contract; its performance is not measured by these two scenes.',
      'Grouping is conservative: explicit opt-in, direct transparent leaf shader meshes, distinct materials, depth test/write off, no material callbacks/culling, MSAA target, autoClear=false and no active XR. Unsupported/scaled/temporal draws retain the legacy path; neighbouring eligible runs preserve input order. Only this bounded optimization is claimed.',
      'First production smoke failed in diagnostic counting because Engine.start synchronously rendered after the measurement restored renderFrame. Its image comparison passed; original scripts/report retained. V2 counts only frames while the measurement wrapper is installed. No application defect or dropped measured frame is inferred from that probe failure.',
      'Menu resource counters reset; no long-duration heap/VRAM soak is claimed. Rare long-frame causes, other MSAA boundaries and asteroid Near cost remain open. Historical cloud bytes and other GPUs/drivers are not covered.'
    ],
    reproduction: [
      'Use the final implementation with matching dependencies. Restore embedded diagnostic sources in an isolated workspace. The runner pins the original base HEAD; adapt that guard explicitly for reproduction without overwriting historical reports. Build with VITE_FS_DRIVER=s3,VITE_S3_URL=https://storage.yandexcloud.net,VITE_FILE_BUCKET=textures,VITE_SHOW_STATS_PANEL=false,VITE_SKY_SOURCE=gaia; npm run build -- --base=/titan-engine-dev/.',
      'Run node benchmark-results/heavy-scenes/run-volume-batch-v2-2026-10-27.mjs --smoke, then without --smoke. Runner freezes dist into a new volume-batch-dist directory and uses the previous production profile solely to verify its untouched build. Restore that historical dependency or remove only that provenance precheck when reproducing elsewhere.',
      'Native suite: TITAN_BROWSER_CHANNEL=chrome,TITAN_BROWSER_GPU=native,npm run test:browser. Synthetic SwiftShader regression: unset TITAN_BROWSER_GPU and run Playwright tests/browser/gpu.e2e.ts --grep "volume MSAA batch". npm test -- --run and npm run lint validate the application.',
      'Decode rawProfile/smoke/reports with gunzipSync(Buffer.from(record.gzipBase64,"base64")); verify byte length and SHA256. All diagnostic sources, test/application changes, full raw profile and logs are embedded. Frozen dist and PNG/RGBA artifacts remain local with hashes; node benchmark-results/heavy-scenes/archive-volume-batch-2026-10-27.mjs --verify checks them locally.'
    ],
    review: existsSync(reviewPath) ? json(reviewPath) : null,
    provenance: paths.map(file => { const bytes = readFileSync(file); return { path: file, bytes: bytes.length, sha256: sha(bytes) } })
  }
  verify(archive); writeFileSync(output, JSON.stringify(archive, null, 2) + '\n'); console.log(output)
}

