import { preview } from 'vite'
import { chromium } from '@playwright/test'
import { cp, readFile, readdir, writeFile } from 'node:fs/promises'
import { existsSync } from 'node:fs'
import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import path from 'node:path'
import assert from 'node:assert/strict'
const root = 'benchmark-results/heavy-scenes/', name = 'volume-batch-2026-10-27', base = 'c5dbb0c96a7853111f4d3760efedfb6b5b9a597a'
const smoke = process.argv.includes('--smoke'), suffix = smoke ? '-smoke' : ''
const output = `${root}${name}${suffix}.json`, frozen = `${root}volume-batch-dist-2026-10-27`
const sha = bytes => createHash('sha256').update(bytes).digest('hex')
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim()
assert.equal(git('rev-parse', 'HEAD'), base)
async function manifest(dir, prefix = '') {
  const rows = []
  for (const entry of await readdir(path.join(dir, prefix), { withFileTypes: true })) {
    const relative = path.posix.join(prefix, entry.name)
    if (entry.isDirectory()) rows.push(...await manifest(dir, relative))
    else if (entry.isFile()) { const bytes = await readFile(path.join(dir, relative)); rows.push({ path: relative, bytes: bytes.length, sha256: sha(bytes) }) }
    else throw Error('Non-file in build')
  }
  return rows.sort((a, b) => a.path.localeCompare(b.path))
}
const buildFiles = await manifest('dist')
if (!existsSync(frozen)) await cp('dist', frozen, { recursive: true, force: false, errorOnExist: true })
assert.deepEqual(await manifest(frozen), buildFiles)
const originalProfile = JSON.parse(await readFile(root + 'gpu-draws-2026-10-27.json', 'utf8'))
for (const file of originalProfile.buildFiles) assert.equal(sha(await readFile(originalProfile.frozenBundle + '/' + file.path)), file.sha256)
const html = await readFile(frozen + '/index.html', 'utf8')
const entryPath = html.match(/<script\b[^>]*\bsrc=["']([^"']+\.js)["']/)?.[1]
assert.ok(entryPath?.startsWith('/titan-engine-dev/assets/'))
const runtimeNames = (await readdir(frozen + '/assets')).filter(file => /^simulationRuntime-.*\.js$/.test(file))
assert.equal(runtimeNames.length, 1)
const runtimePath = '/titan-engine-dev/assets/' + runtimeNames[0]
const paths = [...git('diff', '--name-only', '--', 'src', 'tests').split('\n').filter(Boolean),
  'src/core/graphic/passes/DepthVolumeBatchRenderer.ts', 'tests/graphic/DepthVolumeBatch.spec.ts', 'tests/graphic/volumeBatch.gpu.ts',
  root + 'gpu-draws-2026-10-27.browser.js', root + name + '.browser.js', root + 'run-' + name + '.mjs']
const sourceHashes = Object.fromEntries(await Promise.all([...new Set(paths)].map(async file => [file, sha(await readFile(file))])))
const report = { base, startedAt: new Date().toISOString(), smoke, sourceHashes, buildFiles, frozenBundle: frozen, rows: [], scenes: [], images: [],
  errors: [], warnings: [], assetFailures: [], sourceModuleRequests: [], requests: [], cloudResponses: 0, outcome: 'failed',
  baseline: 'Same candidate production build with supportsDepthVolumeBatch=false on all opted-in volumes; unchanged legacy draw loop. This isolates grouping without a second renderer/runtime. Native synthetic fixtures compare HDR and post-draw depth; real-scene images compare HDR after DepthVolumePass and final RGBA8. No FPS claim.' }
await writeFile(output, JSON.stringify(report, null, 2), { flag: 'wx' })
const save = () => writeFile(output, JSON.stringify(report, null, 2))
let server, browser
try {
  server = await preview({ build: { outDir: frozen }, base: '/titan-engine-dev/', preview: { host: '127.0.0.1', port: 8096, strictPort: true } })
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`); if (r.url().startsWith('https://storage.yandexcloud.net/') && r.ok()) report.cloudResponses++ })
  page.on('requestfailed', r => report.assetFailures.push(`${r.failure()?.errorText} ${r.url()}`))
  page.on('request', r => {
    const url = new URL(r.url()), route = url.pathname.replace(/^\/titan-engine-dev(?=\/)/, '')
    report.requests.push({ origin: url.origin, path: url.pathname, type: r.resourceType() })
    if (/^\/(?:src|@vite|@id|tests)\//.test(route)) report.sourceModuleRequests.push(url.origin + url.pathname)
  })
  const assertDiagnostics = () => { for (const key of ['errors', 'warnings', 'assetFailures', 'sourceModuleRequests']) assert.equal(report[key].length, 0, key) }
  await page.goto('http://127.0.0.1:8096/titan-engine-dev/')
  await page.getByRole('button', { name: /^Run / }).first().waitFor()
  await page.addScriptTag({ path: root + 'gpu-draws-2026-10-27.browser.js', type: 'module' })
  report.connection = await page.evaluate(c => window.__productionFrame.connect(c.entryPath, c.runtimePath), { entryPath, runtimePath })
  await page.addScriptTag({ path: root + name + '.browser.js', type: 'module' })
  await page.evaluate(url => window.__connectVolumeBatch(url).then(() => true), runtimePath)
  for (const [id, actor] of (smoke ? [[13, 135]] : [[13, 135], [12, 127]])) {
    const scene = await page.evaluate(id => window.__productionFrame.selectScenario(id), id)
    assert.doesNotMatch(scene.renderer, /SwiftShader|software|llvmpipe/i)
    report.scenes.push(scene); await save()
    await page.evaluate(actor => window.__productionFrame.setView(actor), actor)
    await page.evaluate(() => window.__productionFrame.settle(64))
    await page.evaluate(() => window.__productionFrame.measure({ mode: 'plain', motion: true, frames: 120 }))
    await page.evaluate(actor => window.__productionFrame.setView(actor), actor)
    await page.evaluate(() => window.__productionFrame.settle(96))
    for (const angle of (smoke ? [0] : [0, 0.27, -0.41])) {
      const result = await page.evaluate(angle => window.__volumeBatch.images(angle), angle)
      for (const record of result.records) {
        const stem = `${root}${name}${suffix}-${id}-${angle}-${record.label}`
        const rgba = Buffer.from(record.rgba, 'base64'), png = Buffer.from(record.png, 'base64')
        assert.equal(sha(rgba), record.rgbaSha256)
        await writeFile(stem + '.rgba', rgba, { flag: 'wx' }); await writeFile(stem + '.png', png, { flag: 'wx' })
        delete record.rgba; delete record.png
        record.rgbaPath = stem + '.rgba'; record.pngPath = stem + '.png'; record.pngSha256 = sha(png)
      }
      report.images.push({ id, ...result }); await save()
      console.log('VOLUME_BATCH_IMAGE', id, angle, JSON.stringify({ candidate: result.candidate, control: result.control }))
      for (const check of [result.candidate, result.control]) { assert.equal(check.rgba.differences, 0); assert.equal(check.hdr.differences, 0) }
      assertDiagnostics()
    }
    const windows = smoke ? [{ mode: 'passes', motion: true, batch: false, repetition: 0 }, { mode: 'passes', motion: true, batch: true, repetition: 0 }] :
      ['passes', 'gpu-frame'].flatMap(mode => [false, true].flatMap(motion =>
        (mode === 'passes' ? [0, 1] : [0]).flatMap(repetition => (repetition ? [true, false] : [false, true]).map(batch => ({ mode, motion, repetition, batch })))))
    for (const window of windows) {
      const view = await page.evaluate(actor => window.__productionFrame.setView(actor), actor)
      await page.evaluate(() => window.__productionFrame.settle(64))
      const result = await page.evaluate(options => window.__volumeBatch.measure(options), { ...window, frames: smoke ? 8 : 120 })
      report.rows.push({ id, ...window, view, ...result }); await save()
      console.log('VOLUME_BATCH_GPU', id, JSON.stringify(window), JSON.stringify({ resolves: [...new Set(result.resolves)], gpu: result.summary.gpu }))
      assertDiagnostics()
    }
    report.scenes.at(-1).afterMenu = await page.evaluate(() => window.__productionFrame.menu())
    await save()
  }
  assertDiagnostics(); assert.ok(report.cloudResponses > 0)
  assert.deepEqual(await manifest(frozen), buildFiles)
  for (const [file, hash] of Object.entries(sourceHashes)) assert.equal(sha(await readFile(file)), hash, file)
  report.outcome = 'completed'
} catch (error) { report.failure = error.stack || error.message; console.error(error); process.exitCode = 1 }
finally { report.finishedAt = new Date().toISOString(); await save(); await browser?.close(); if (server) await new Promise(resolve => server.httpServer.close(resolve)) }

