// Diagnostic-only capability toggle on the built production runtime. No source imports.
window.__connectVolumeBatch = async runtimeUrl => {
  const runtime = await import(runtimeUrl)
  const get = name => {
    const container = runtime.getInitializedSimulationRuntime().container
    const keys = [...container.bindings.keys()].filter(key => typeof key === 'object' && key.name === name)
    if (keys.length !== 1) throw Error('Missing service ' + name)
    return container.get(keys[0])
  }
  const preserve = (object, key) => {
    const descriptor = Object.getOwnPropertyDescriptor(object, key)
    return () => {
      if (descriptor) Object.defineProperty(object, key, descriptor); else delete object[key]
      const after = Object.getOwnPropertyDescriptor(object, key)
      if (!!after !== !!descriptor || (descriptor && ['value', 'get', 'set', 'writable', 'configurable', 'enumerable'].some(field => after[field] !== descriptor[field]))) throw Error('Failed restoration: ' + key)
    }
  }
  const setBatch = enabled => {
    const volumes = get('DepthVolumeRegistry').volumes().filter(volume => volume.supportsDepthVolumeBatch === true)
    if (!volumes.length) throw Error('No batch-capable production volumes')
    const restore = volumes.map(volume => preserve(volume, 'supportsDepthVolumeBatch'))
    volumes.forEach(volume => { volume.supportsDepthVolumeBatch = enabled })
    return () => restore.forEach(fn => fn())
  }
  const hardware = () => {
    const renderer = get('Renderer'), gl = renderer.getContext(), composer = get('Postprocessing').composer
    const binding = gl.getParameter(gl.RENDERBUFFER_BINDING)
    try {
      return [composer.inputBuffer, composer.outputBuffer].map(target => ({
        width: target.width, height: target.height, requestedSamples: target.samples,
        colorRenderbuffers: (renderer.properties.get(target).__webglColorRenderbuffer ?? []).map(buffer => {
          gl.bindRenderbuffer(gl.RENDERBUFFER, buffer)
          return { samples: gl.getRenderbufferParameter(gl.RENDERBUFFER, gl.RENDERBUFFER_SAMPLES), format: gl.getRenderbufferParameter(gl.RENDERBUFFER, gl.RENDERBUFFER_INTERNAL_FORMAT) }
        })
      }))
    } finally { gl.bindRenderbuffer(gl.RENDERBUFFER, binding) }
  }
  const encoded = bytes => {
    let value = ''
    for (let i = 0; i < bytes.length; i += 16384) value += String.fromCharCode(...bytes.subarray(i, i + 16384))
    return btoa(value)
  }
  const hash = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(value => value.toString(16).padStart(2, '0')).join('')
  const difference = (a, b) => {
    if (a.length !== b.length) throw Error('Different buffer sizes')
    let count = 0, max = 0
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) { count++; max = Math.max(max, Math.abs(a[i] - b[i])) }
    return { elements: a.length, differences: count, max }
  }
  return window.__volumeBatch = {
    hardware,
    async measure(options) {
      const renderer = get('Renderer'), gl = renderer.getContext(), pp = get('Postprocessing')
      const pass = pp.composer.passes.find(item => item.name === 'DepthVolumePass')
      const restoreBatch = setBatch(options.batch), restoreRender = preserve(pass, 'render'), restoreBlit = preserve(gl, 'blitFramebuffer')
      const originalRender = pass.render, originalBlit = gl.blitFramebuffer, resolves = []
      let active = false, count = 0
      pass.render = function (...args) {
        active = true; count = 0
        try { return originalRender.apply(this, args) }
        finally { active = false; resolves.push(count) }
      }
      gl.blitFramebuffer = function (...args) { if (active) count++; return originalBlit.apply(this, args) }
      try {
        const result = await window.__productionFrame.measure(options)
        if (resolves.length !== options.frames) throw Error('Resolve count/frame mismatch: ' + resolves.length)
        return { ...result, resolves, hardware: hardware() }
      } finally { restoreRender(); restoreBlit(); restoreBatch() }
    },
    async images(angle) {
      const engine = get('Engine'), renderer = get('Renderer'), gl = renderer.getContext(), pp = get('Postprocessing'), camera = get('Camera')
      const pass = pp.composer.passes.find(item => item.name === 'DepthVolumePass')
      const position = camera.position.clone(), quaternion = camera.quaternion.clone()
      const restoreRender = preserve(pass, 'render'), originalRender = pass.render
      let capture = false, hdr = null
      const records = [], buffers = []
      engine.stop()
      try {
        camera.rotateY(angle); camera.position.addScaledVector(position.clone().set(1, 0, 0).applyQuaternion(quaternion), angle)
        camera.updateMatrixWorld(true)
        pass.render = function (...args) {
          const value = originalRender.apply(this, args)
          if (capture) {
            const target = args[1]
            hdr = new Uint16Array(target.width * target.height * 4)
            renderer.readRenderTargetPixels(target, 0, 0, target.width, target.height, hdr)
          }
          return value
        }
        for (const [label, batch] of [['baseline-before', false], ['candidate', true], ['baseline-after', false]]) {
          const restoreBatch = setBatch(batch)
          try {
            for (const item of pp.composer.passes) {
              const history = item.scaled?.history
              if (history) for (const frame of history.records.values()) history.invalidate(frame)
            }
            for (let frame = 0; frame < 16; frame++) { capture = frame === 15; pp.render(0) }
            if (!hdr) throw Error('No HDR capture')
            const rgba = new Uint8Array(gl.drawingBufferWidth * gl.drawingBufferHeight * 4)
            gl.readPixels(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight, gl.RGBA, gl.UNSIGNED_BYTE, rgba)
            if (gl.getError()) throw Error('Image WebGL error')
            buffers.push({ rgba, hdr })
            records.push({ label, batch, rgba: encoded(rgba), png: renderer.domElement.toDataURL('image/png').split(',')[1],
              hdrBytes: hdr.byteLength, hdrSha256: await hash(hdr), rgbaSha256: await hash(rgba) })
          } finally { restoreBatch() }
        }
        return { angle, camera: camera.position.toArray(), orientation: camera.quaternion.toArray(), records, hardware: hardware(),
          candidate: { rgba: difference(buffers[0].rgba, buffers[1].rgba), hdr: difference(buffers[0].hdr, buffers[1].hdr) },
          control: { rgba: difference(buffers[0].rgba, buffers[2].rgba), hdr: difference(buffers[0].hdr, buffers[2].hdr) } }
      } finally { capture = false; restoreRender(); camera.position.copy(position); camera.quaternion.copy(quaternion); camera.updateMatrixWorld(true); engine.start() }
    }
  }
}

