        const submitted = workload[key] ??= { instances: Array(frames).fill(0), elements: Array(frames).fill(0), calls: Array(frames).fill(0) }
        const instances = object.isInstancedMesh ? object.count : geometry.isInstancedBufferGeometry ? Math.min(geometry.instanceCount, geometry._maxInstanceCount ?? Infinity) : 1
        if (!Number.isFinite(instances) || instances < 0) throw Error('Invalid submitted instance count')
