      const result = await page.evaluate(angle => window.__volumeBatch.images(angle), angle)
      for (const record of result.records) {
        const stem = `${root}${name}${suffix}-${id}-${angle}-${record.label}`
        const rgba = Buffer.from(record.rgba, 'base64'), png = Buffer.from(record.png, 'base64')
        assert.equal(sha(rgba), record.rgbaSha256)
        await writeFile(stem + '.rgba', rgba, { flag: 'wx' }); await writeFile(stem + '.png', png, { flag: 'wx' })
        delete record.rgba; delete record.png
        record.rgbaPath = stem + '.rgba'; record.pngPath = stem + '.png'; record.pngSha256 = sha(png)
      }
      report.images.push({ id, ...result }); await save()
      console.log('VOLUME_BATCH_IMAGE', id, angle, JSON.stringify({ candidate: result.candidate, control: result.control }))
      for (const check of [result.candidate, result.control]) { assert.equal(check.rgba.differences, 0); assert.equal(check.hdr.differences, 0) }
      assertDiagnostics()
    }
    const windows = smoke ? [{ mode: 'passes', motion: true, batch: false, repetition: 0 }, { mode: 'passes', motion: true, batch: true, repetition: 0 }] :
      ['passes', 'gpu-frame'].flatMap(mode => [false, true].flatMap(motion =>
        (mode === 'passes' ? [0, 1] : [0]).flatMap(repetition => (repetition ? [true, false] : [false, true]).map(batch => ({ mode, motion, repetition, batch })))))
    for (const window of windows) {
      const view = await page.evaluate(actor => window.__productionFrame.setView(actor), actor)
      await page.evaluate(() => window.__productionFrame.settle(64))
      const result = await page.evaluate(options => window.__volumeBatch.measure(options), { ...window, frames: smoke ? 8 : 120 })
      report.rows.push({ id, ...window, view, ...result }); await save()
      console.log('VOLUME_BATCH_GPU', id, JSON.stringify(window), JSON.stringify({ resolves: [...new Set(result.resolves)], gpu: result.summary.gpu }))
      assertDiagnostics()
    }
    report.scenes.at(-1).afterMenu = await page.evaluate(() => window.__productionFrame.menu())
    await save()
  }
  assertDiagnostics(); assert.ok(report.cloudResponses > 0)
  assert.deepEqual(await manifest(frozen), buildFiles)
  for (const [file, hash] of Object.entries(sourceHashes)) assert.equal(sha(await readFile(file)), hash, file)
  report.outcome = 'completed'
} catch (error) { report.failure = error.stack || error.message; console.error(error); process.exitCode = 1 }
finally { report.finishedAt = new Date().toISOString(); await save(); await browser?.close(); if (server) await new Promise(resolve => server.httpServer.close(resolve)) }
